<template><el-card shadow="never"><template #header><div class="head"><div><b>测试环境</b><p>维护被测服务地址、健康检查与发布修订。</p></div><el-button type="primary" @click="openCreate">新建环境</el-button></div></template><el-table v-loading="loading" :data="items"><el-table-column prop="name" label="环境名称" width="160"/><el-table-column prop="base_url" label="被测服务 URL" min-width="260"/><el-table-column prop="healthcheck_path" label="健康路径" width="150"/><el-table-column label="状态" width="110"><template #default="{row}"><el-tag :type="row.status==='published'?'success':'info'">{{ row.status==='published'?'已发布':'草稿' }}</el-tag></template></el-table-column><el-table-column label="操作" width="190"><template #default="{row}"><el-button link @click="health(row)">健康检查</el-button><el-button v-if="row.status!=='published'" link type="primary" @click="publish(row)">发布</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table><el-empty v-if="!loading&&!items.length" description="暂无测试环境，添加后测试计划才可选择稳定的被测服务"/></el-card><el-dialog v-model="visible" title="新建测试环境" width="520px"><el-form label-position="top"><el-form-item label="环境名称"><el-input v-model="form.name" placeholder="如：集成测试环境"/></el-form-item><el-form-item label="被测服务 URL"><el-input v-model="form.base_url" placeholder="http://service:8080"/></el-form-item><el-form-item label="健康检查路径"><el-input v-model="form.healthcheck_path" placeholder="/health"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="create">保存草稿</el-button></template></el-dialog></template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{useRoute}from'vue-router';import{ElMessage,ElMessageBox}from'element-plus';import{environmentApi}from'@/api';const projectId=String(useRoute().params.id),loading=ref(false),items=ref<any[]>([]),visible=ref(false),form=reactive({name:'',description:'',base_url:'',healthcheck_path:'/health',auth_strategy:'none',auth_config:{}});async function load(){loading.value=true;try{const r:any=await environmentApi.list(projectId);items.value=r?.data?.items||r?.data?.list||r?.data||[]}finally{loading.value=false}}function openCreate(){Object.assign(form,{name:'',base_url:'',healthcheck_path:'/health'});visible.value=true}async function create(){await environmentApi.create(projectId,form);ElMessage.success('环境草稿已创建');visible.value=false;load()}async function health(row:any){const r:any=await environmentApi.healthcheck(row.id);const d=r?.data;ElMessage.success(`检查完成：HTTP ${d?.status_code??'可用'}`)}async function publish(row:any){await environmentApi.publish(row.id);ElMessage.success('环境已发布并生成修订');load()}async function remove(row:any){await ElMessageBox.confirm(`删除环境“${row.name}”？`,'删除环境',{type:'warning'});await environmentApi.remove(row.id);ElMessage.success('已删除');load()}onMounted(load)</script>
<style scoped>.head{display:flex;justify-content:space-between;align-items:flex-start}.head p{margin:5px 0 0;color:var(--app-text-secondary);font-size:13px}</style>
